/// <reference path="../pb_data/types.d.ts" />

// ── «Прочитать все» — отметка всех непрочитанных уведомлений одним запросом ──
//
// Бейдж колокольчика рисуется по серверному итогу — числу ВСЕХ непрочитанных строк
// пользователя, — в то время как в React state живёт одна страница (20 строк) плюс
// вытянутые по «Показать ещё». Раньше кнопка «Прочитать все» обходила PATCH только
// строки из state, поэтому при ~130 непрочитанных сервер продолжал рапортовать ~130,
// и бейдж навсегда оставался «99+». Теперь отметка выполняется на сервере: один POST
// помечает прочитанными все непрочитанные уведомления этого пользователя.
//
// Идентификатор пользователя берётся ТОЛЬКО из `e.auth`: присланное клиентом значение
// не читается, так что чужой список подсунуть нельзя. Прочие отметки о прохождении
// отсекает `$apis.requireAuth('users')` — без валидного токена коллекции `users`
// миддлварь отвечает 401 до хендлера (страховка ниже — только на случай, когда маршрут
// однажды перерегистрируют уже без неё).
//
// Каждая отметка уходит и в реальный времени (SSE `update` записи), поэтому параллельный
// колокольчик в другом окне спишет эти строки из своего бейджа по мере эха, а его итог
// сойдётся с нулём на ближайшем re-check.

routerAdd(
  'POST',
  '/api/collections/notifications/mark-all-read',
  (e) => {
    var auth = e.auth;
    if (!auth) {
      return e.json(401, { code: 401, message: 'Требуется авторизация.', data: {} });
    }

    var updated = 0;
    try {
      var unread = $app.findRecordsByFilter(
        'notifications',
        'user_id = "' + String(auth.id) + '" && read = false',
        '',
        0,
        0,
      );
      for (var i = 0; i < unread.length; i++) {
        try {
          unread[i].set('read', true);
          $app.save(unread[i]);
        } catch (err) {
          // Сбой на одной строке не откатывает остальные: отмеченные остаются
          // прочитанными, несостоявшиеся строки ещё раз придёт разметить клик
          // или ближайший re-check.
          console.error('[notifications:mark-all-read]', String(err));
          continue;
        }
        updated += 1;
      }
    } catch (err) {
      console.error('[notifications:mark-all-read]', String(err));
      return e.json(500, {
        code: 500,
        message: 'Не удалось отметить уведомления как прочитанные.',
        data: {},
      });
    }

    return e.json(200, { updated: updated });
  },
  $apis.requireAuth('users'),
);
